SELECT e.chunk_text AS chunkText, e.doc_id AS docId, d.title AS title, e.chunk_index AS chunkIndex, (e.embedding <-> #{queryVector,typeHandler=com.vc.knowledge.handler.VectorTypeHandler}) AS score FROM knowledge_embedding e JOIN knowledge_doc d ON d.id = e.doc_id WHERE d.deleted = false AND d.is_vectorized = true AND e.doc_id IN
#{id}
AND e.embedding_model = #{embeddingModel}
AND (e.embedding <-> #{queryVector,typeHandler=com.vc.knowledge.handler.VectorTypeHandler}) <= #{distanceThreshold}
ORDER BY score ASC LIMIT #{limit}

